class Solution {
  public int integerReplacement(int n) {
    long x = n;
    int steps = 0;
    while (x != 1) {
      if (x % 2 == 0) x /= 2;
      else if (x == 3 || (x & 3) == 1) x--; // ...01 -> subtract so the next steps divide
      else x++; // ...11 -> add to clear trailing ones
      steps++;
    }
    return steps;
  }
}
